+import * as fs from "node:fs";
+import * as nodePath from "node:path";
+
+interface PathRule {
+  pattern: string;
+  targets: string[];
+  baseDir: string;
+}
+
+interface LoadedConfig {
+  dir: string;
+  baseUrl?: string;
+  paths: PathRule[];
+}
+
+export type TypeScriptModuleResolver = (
+  sourcePath: string,
+  specifier: string,
+  kind?: "runtime" | "types",
