+const SOURCE_SUFFIXES = [".ts", ".tsx", ".d.ts", ".js", ".jsx", ".mjs", ".cjs"];
+
+function normalizePath(value: string): string {
+  return nodePath.posix.normalize(value.replace(/\\/g, "/"));
