+    typeof compilerOptions.baseUrl === "string"
+      ? nodePath.resolve(configDir, compilerOptions.baseUrl)
+      : undefined;
+  const baseUrl = ownBaseUrl ?? parent?.baseUrl;
+  let paths = parent?.paths ?? [];
