+    const pathBase = baseUrl ?? configDir;
+    paths = Object.entries(compilerOptions.paths as Record<string, unknown>)
+      .filter(
+        (entry): entry is [string, string[]] =>
+          Array.isArray(entry[1]) && entry[1].every((target) => typeof target === "string"),
