+          );
+          if (matches.length > 0) return matches;
+        }
+        mappedExplicitly = rule.pattern !== "*";
+        break;
+      }
+      // TypeScript tries `paths` first and then falls back to `baseUrl`, so a
+      // failed rule must not short-circuit the baseUrl lookup.
